function output_dir=plot_q8_dom_roi_long45_allqc(phase_key)
% Three broad ROI/laterality figures for Q8 DOM, HIHE - LILE.
if nargin<1,phase_key="dom";end;phase_key=lower(string(phase_key));phase_display=upper(phase_key);repo_root=fileparts(fileparts(fileparts(mfilename('fullpath'))));root=fullfile(repo_root,'results',sprintf('q8_hihe_vs_lile_%s',phase_key),'cohort_specification');output_dir=fullfile(root,'figures_long45_allQC');if ~isfolder(output_dir),mkdir(output_dir);end
I=readtable(fullfile(root,sprintf('q8_HIHE_minus_LILE_%s_individual_ROI_long45_allQC_n30.csv',phase_key)),'TextType','string');G=readtable(fullfile(root,sprintf('q8_HIHE_minus_LILE_%s_group_ROI_long45_allQC_n30.csv',phase_key)),'TextType','string');C=readtable(fullfile(root,sprintf('q8_HIHE_minus_LILE_%s_group_channel_long45_allQC_n30.csv',phase_key)),'TextType','string');hbs=["HbO","HbR"];K=unique(I(I.hemoglobin=="HbO",{'roi','laterality'}),'rows','stable');labs=strcat(K.roi," | ",K.laterality);
f=figure('Color','w','Position',[100 100 1800 1050]);set(f,'DefaultTextColor','k');tiledlayout(2,1,'TileSpacing','compact','Padding','compact');
for h=1:2,U=I(I.hemoglobin==hbs(h),:);M=nan(30,height(K));for k=1:height(K),V=U(U.roi==K.roi(k)&U.laterality==K.laterality(k),:);[~,o]=sort(V.subject_id);M(:,k)=V.mean_contrast_beta(o);end;nexttile;lim=max(abs(M(:)),[],'omitnan');if ~isfinite(lim)||lim==0,lim=1;end;imagesc(M,[-lim lim]);colormap(gca,bwr(256));cb=colorbar;cb.Color='k';set(gca,'XTick',1:height(K),'XTickLabel',labs,'XTickLabelRotation',35,'YTick',1:30,'YTickLabel',compose('%03d',1:30),'FontSize',9,'Color','w','XColor','k','YColor','k');xlabel('Broad ROI | laterality','Color','k');ylabel('Subject','Color','k');title(sprintf('%s: subject-level ROI mean beta (HIHE - LILE)',hbs(h)),'Color','k');end
sgtitle(sprintf('Q8 %s layer 1: individual ROI profiles | all 45 long channels; QC flags retained',phase_display),'Color','k');exportgraphics(f,fullfile(output_dir,sprintf('q8_%s_layer1_individual_roi_heatmaps_long45_allQC.png',phase_key)),'Resolution',220);close(f);
f=figure('Color','w','Position',[100 100 1800 1050]);set(f,'DefaultTextColor','k');tiledlayout(1,2,'TileSpacing','compact','Padding','compact');
for h=1:2,U=G(G.hemoglobin==hbs(h),:);[~,o]=sort(U.mean_contrast_beta);U=U(o,:);nexttile;hold on;y=1:height(U);errorbar(U.mean_contrast_beta,y,U.se_contrast_beta,'horizontal','o','LineWidth',1.2,'MarkerFaceColor',[.1 .3 .55],'Color',[.1 .3 .55]);xline(0,'-','Color',[.4 .4 .4]);sig=U.q_value_bh_fdr<.05;plot(U.mean_contrast_beta(sig),y(sig),'rp','MarkerFaceColor','r','MarkerSize',9);set(gca,'YDir','reverse','YTick',y,'YTickLabel',strcat(U.roi," | ",U.laterality),'FontSize',10,'Color','w','XColor','k','YColor','k');xlabel('Group mean beta (HIHE - LILE) +/- SE','Color','k');ylabel('ROI | laterality','Color','k');title(sprintf('%s: 30-subject ROI effects',hbs(h)),'Color','k');grid on;end
sgtitle(sprintf('Q8 %s layer 2: group ROI effects | red pentagram = BH-FDR q < .05',phase_display),'Color','k');exportgraphics(f,fullfile(output_dir,sprintf('q8_%s_layer2_group_roi_effects_long45_allQC.png',phase_key)),'Resolution',220);close(f);
f=figure('Color','w','Position',[100 100 1900 700]);set(f,'DefaultTextColor','k');tiledlayout(2,1,'TileSpacing','compact','Padding','compact');
for h=1:2,U=C(C.hemoglobin==hbs(h),:);[~,o]=sort(U.channel);U=U(o,:);nexttile;hold on;v=U.mean_contrast_beta';lim=max(abs(v),[],'omitnan');if ~isfinite(lim)||lim==0,lim=1;end;imagesc(v,[-lim lim]);colormap(gca,bwr(256));cb=colorbar;cb.Color='k';set(gca,'YTick',1,'YTickLabel',hbs(h),'XTick',1:height(U),'XTickLabel',compose('ch%d',U.channel),'XTickLabelRotation',45,'FontSize',9,'Color','w','XColor','k','YColor','k');xlabel('Long channel','Color','k');ylabel('Hemoglobin','Color','k');title(sprintf('%s: group mean channel beta; black dot = uncorrected p < .05',hbs(h)),'Color','k');sig=U.p_value<.05;plot(find(sig),ones(sum(sig),1),'ko','MarkerFaceColor','k','MarkerSize',5);end
sgtitle(sprintf('Q8 %s layer 3: 45 long-channel group effects | HIHE - LILE; QC flags retained',phase_display),'Color','k');exportgraphics(f,fullfile(output_dir,sprintf('q8_%s_layer3_long_channel_effects_long45_allQC.png',phase_key)),'Resolution',220);close(f);fprintf('Saved Q8 %s figures to %s\n',phase_display,output_dir);
end
function c=bwr(n),h=floor(n/2);c=[[linspace(.1,1,h)' linspace(.3,1,h)' ones(h,1)];[ones(n-h,1) linspace(1,.15,n-h)' linspace(1,.15,n-h)']];end
